#!/usr/bin/env python3
"""Build an instrumented standalone mGBA Lua script from a pristine FRLG script.

This is a measurement wrapper, never modifies the source in place.
Benchmark the original and optimized build with equivalent wrapper overhead.
"""
import argparse
import json
from pathlib import Path
import re

PREFIX = r'''
-- BEGIN REAL mGBA PROBE: generated by tests/real_mgba/build_probe.py
local __probeTick, __probeFrames, __probeRenders, __probeCPU = 0, 0, 0, 0
local __probeMaxCPU = 0
local __probeLastSecond = os.time()
local __probeOut = __PROBE_OUT__
local __probeEvents = __PROBE_EVENTS__
local __probeEnableTrace = __PROBE_TRACE__
local function __probeEvent(kind, data)
 if not __probeEnableTrace then return end
 local fh = io.open(__probeEvents, "a")
 if fh then
  fh:write(string.format("%d\t%d\t%s\t%s\n", __probeTick, emu:currentFrame(), kind, tostring(data or "")))
  fh:close()
 end
end
local function __probeDump(elapsed)
 if elapsed <= 0 or __probeFrames == 0 then return end
 local fh = io.open(__probeOut, "a")
 if fh then
  fh:write(string.format("%d\t%d\t%d\t%d\t%.7f\t%.7f\n",
      os.time(), elapsed, __probeFrames, __probeRenders, __probeCPU, __probeMaxCPU))
  fh:close()
 end
 __probeFrames, __probeRenders, __probeCPU, __probeMaxCPU = 0, 0, 0, 0
end
-- END REAL mGBA PROBE PRELUDE
'''
SUFFIX = r'''
-- BEGIN REAL mGBA PROBE FRAME WRAPPER
local __probeOriginalUpdateBuffers = updateBuffers
function updateBuffers()
 local before = os.clock()
 __probeOriginalUpdateBuffers()
 local duration = os.clock() - before
 __probeCPU = __probeCPU + duration
 if duration > __probeMaxCPU then __probeMaxCPU = duration end
 __probeFrames, __probeTick = __probeFrames + 1, __probeTick + 1
 local second = os.time()
 if second > __probeLastSecond then
  __probeDump(second - __probeLastSecond)
  __probeLastSecond = second
 elseif second < __probeLastSecond then
  __probeLastSecond = second
 end
end
-- END REAL mGBA PROBE FRAME WRAPPER
'''

def replace_once(src: str, old: str, new: str, description: str) -> str:
    count = src.count(old)
    if count != 1:
        raise RuntimeError(f"{description}: expected one match, got {count}")
    return src.replace(old, new, 1)

def build(src: str, log_path: Path, event_path: Path, trace: bool) -> str:
    source = src.replace('\r\n', '\n')
    if 'BEGIN REAL mGBA PROBE' in source:
        raise RuntimeError('source already instrumented')
    source = replace_once(source, 'function updateCaptureBuffer()\n',
                          'function updateCaptureBuffer()\n __probeRenders = __probeRenders + 1\n', 'UI count')
    if trace:
        source = replace_once(source, 'function initialSeedWritten()\n',
                              'function initialSeedWritten()\n __probeEvent("WATCH", emu:read16(0x02020000))\n', 'Watchpoint trace')
        for label, match, event in (
            ('seed save', 'continueScreen = emu:saveStateBuffer()', 'SEED_SAVE'),
            ('seed retry', 'emu:loadStateBuffer(continueScreen)', 'SEED_RETRY'),
            ('seed success', 'initialSeedFoundFlag = true', 'SEED_FOUND'),
            ('TID save', 'insertionNameState = emu:saveStateBuffer()', 'TID_SAVE'),
            ('TID retry', 'emu:loadStateBuffer(insertionNameState)', 'TID_RETRY'),
            ('TID success', 'TIDFoundFlag = true', 'TID_FOUND'),
        ):
            source = replace_once(source, match, match + '\n   __probeEvent("' + event + '", emu:read16(0x02020000))', label)
    prelude = PREFIX.replace('__PROBE_OUT__', json.dumps(log_path.as_posix(), ensure_ascii=False))
    prelude = prelude.replace('__PROBE_EVENTS__', json.dumps(event_path.as_posix(), ensure_ascii=False))
    prelude = prelude.replace('__PROBE_TRACE__', 'true' if trace else 'false')
    source = prelude + '\n' + source
    source = replace_once(source, 'emu:reset()\ninitializeBuffers()', SUFFIX + '\nemu:reset()\ninitializeBuffers()', 'callback wrapper')
    return source

def main():
    p=argparse.ArgumentParser(description=__doc__)
    p.add_argument('--source', required=True, type=Path)
    p.add_argument('--label', required=True)
    p.add_argument('--output-dir', type=Path, default=Path('tests/real_mgba/output'))
    p.add_argument('--trace', action='store_true', help='event tracing costs extra IO; do not use for FPS runs')
    args=p.parse_args()
    if not re.fullmatch(r'[A-Za-z0-9_-]{1,48}', args.label): p.error('--label must be 1-48 ASCII letters/digits/_/-')
    args.output_dir.mkdir(parents=True, exist_ok=True)
    log=(args.output_dir/(args.label+'_perf.tsv')).resolve()
    ev=(args.output_dir/(args.label+'_events.tsv')).resolve()
    target=args.output_dir/(args.label+'_instrumented.lua')
    target.write_text(build(args.source.read_text(encoding='utf-8-sig'), log, ev, args.trace), encoding='utf-8')
    log.write_text('timestamp\telapsed_s\tframe_callbacks\trender_calls\tcallback_cpu_s\tmax_callback_cpu_s\n',encoding='utf-8')
    if args.trace: ev.write_text('tick\temulator_frame\tevent\tseed_value\n',encoding='utf-8')
    print(f'Generated: {target.resolve()}')
    print(f'Performance log: {log}')
    if args.trace: print(f'Event log: {ev}')
    print('Load generated Lua in mGBA AFTER starting FRLG. This will reset the game like upstream.')

if __name__=='__main__': main()
